1	import { notFound } from "next/navigation";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { serverRootPassword } from "@/lib/sftp";
5	import { vmStatus, listSnapshots, listBackups } from "@/lib/proxmox";
6	import { AutoRefresh } from "@/components/AutoRefresh";
7	import { ServerControls } from "@/components/ServerControls";
8	import { RenewalCard } from "@/components/SubscriptionControls";
9	import { StatusDot, Badge, fmtBytes, fmtMoney } from "@/components/ui/primitives";
10	import { MeterBar } from "@/components/ui/charts";
11	import { ServerTabs } from "@/components/customer/ServerTabs";
12	import { MetricsPanel } from "@/components/customer/MetricsPanel";
13	import { DiskUsageChart } from "@/components/customer/DiskUsageChart";
14	import { ServerRename } from "@/components/customer/ServerRename";
15	import { Console } from "@/components/customer/Console";
16	import { FileManager } from "@/components/customer/FileManager";
