24	import { ReinstallOs } from "@/components/customer/ReinstallOs";
25	import { BackupSchedule } from "@/components/customer/BackupSchedule";
26	import { ActivityTimeline } from "@/components/customer/ActivityTimeline";
27	import { SftpAccess } from "@/components/customer/SftpAccess";
28	import { GameAutoUpdate } from "@/components/customer/GameAutoUpdate";
29	import { BackupRestore } from "@/components/customer/BackupRestore";
30	import { GameSettings } from "@/components/customer/GameSettings";
31	import { GAME_FAMILIES, type GameFamily } from "@/lib/games";
32	import { familyFor, schemaFor, isValidVariant, validateConfig } from "@/lib/game-config";
33	
34	export const dynamic = "force-dynamic";
35	
36	function fmtUptime(seconds: number): string {
37	  if (!seconds || seconds <= 0) return "—";
38	  const d = Math.floor(seconds / 86400);
39	  const h = Math.floor((seconds % 86400) / 3600);
40	  const m = Math.floor((seconds % 3600) / 60);
41	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
42	}
43	
44	type LiveStats = {
45	  cpu?: number;
46	  mem?: number;
47	  maxmem?: number;
48	  uptime?: number;
49	  netin?: number;
50	  netout?: number;
51	} | null;
52	
53	export default async function ServerPage({
54	  params,
55	  searchParams,
56	}: {
57	  params: Promise<{ id: string }>;
58	  searchParams: Promise<{ tab?: string }>;
59	}) {
60	  const [{ id }, { tab }] = await Promise.all([params, searchParams]);
61	  const user = await requireUser();
62	  const server = await db.server.findUnique({
63	    where: { id },
64	    include: {
65	      plan: true,
66	      osTemplate: true,
67	      project: true,
68	      portForwards: { orderBy: { publicPort: "asc" } },
69	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
70	      dedicatedIp: true,
71	    },
72	  });
73	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
74	
75	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
76	  // display value through the decrypt fallback (legacy plaintext rows still work).
77	  const rootPassword = serverRootPassword(server);
78	
79	  const [projects, activePlans, osTemplates] = await Promise.all([
80	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
81	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
82	    db.osTemplate.findMany({
83	      where: { active: true, category: "PLAIN_OS" },
84	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
85	    }),
86	  ]);
87	
88	  const publicIp = process.env.PUBLIC_IP ?? "";
89	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
90	  const busy =
91	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
92	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
93	
94	  let live: LiveStats = null;
95	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
96	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
97	  let pveUnavailable = false;
98	
99	  if (server.vmid && steady) {
100	    const results = await Promise.allSettled([
101	      vmStatus(server.vmid),
102	      listSnapshots(server.vmid),
103	      listBackups(server.vmid),
104	    ]);
105	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
106	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
107	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
108	    pveUnavailable = results.some((r) => r.status === "rejected");
109	  }
110	
111	  const sshCommand = server.sshPort ? `ssh root@${publicIp} -p ${server.sshPort}` : null;
112	
113	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
114	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
115	  const dedicated = !!server.dedicatedIp;
116	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
117	  const sftpPort = dedicated ? 22 : server.sshPort;
118	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
119	
120	  // Per-game customization (only for game servers with a customization schema).
121	  const gameFamily = familyFor(server);
122	  const gameSchema = schemaFor(gameFamily);
123	  const gameVariant =
124	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
125	      ? server.gameVariant
126	      : gameSchema?.defaultVariant ?? "";
127	  const gameValidated = gameFamily
128	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
129	    : null;
130	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
131	
132	  /* ---------- Tab: Overview ---------- */
133	  const overview = (
134	    <div className="grid gap-6 md:grid-cols-2">
135	      <div className="card">
136	        <h2 className="mb-4 font-semibold">Access</h2>
137	        <dl className="space-y-3 text-sm">
138	          <div>
139	            <dt className="text-slate-400">SSH command</dt>
140	            <dd className="mt-1 flex items-center gap-2">
141	              <code className="rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
142	                {sshCommand ?? "provisioning…"}
143	              </code>
144	              {sshCommand && <CopyText text={sshCommand} />}
145	            </dd>
146	          </div>
147	          <div className="flex items-center justify-between">
148	            <dt className="text-slate-400">Root password</dt>
149	            <dd>
150	              {rootPassword ? (
151	                <RevealPassword password={rootPassword} />
152	              ) : (
153	                <span className="text-slate-500">—</span>
154	              )}
155	            </dd>
156	          </div>
157	          <div className="flex items-center justify-between">
158	            <dt className="text-slate-400">Private IP</dt>
159	            <dd className="font-mono text-xs">{server.ipAddress ?? "—"}</dd>
160	          </div>
161	        </dl>
162	        <div className="divider" />
163	        <div className="flex flex-wrap items-center justify-between gap-2">
164	          <p className="text-xs text-slate-500">
165	            Lost access or rotating credentials? Generate a fresh root password.
166	          </p>
167	          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
168	        </div>
169	      </div>
170	
171	      <SftpAccess
172	        host={sftpHost}
173	        port={sftpPort}
174	        password={rootPassword}
175	        dedicated={dedicated}
176	      />
177	
178	      {isGameServer && (
179	        <div className="md:col-span-2">
180	          <GameAutoUpdate
181	            serverId={server.id}
182	            gameName={server.osTemplate.name}
183	            autoUpdate={server.autoUpdate}
184	            canUpdate={server.status === "RUNNING"}
185	            busy={busy}
186	          />
187	        </div>
188	      )}
189	
190	      {server.gamePlanId && gameSchema && (
191	        <div className="md:col-span-2">
192	          <GameSettings
193	            serverId={server.id}
194	            schema={gameSchema}
195	            variant={gameVariant}
196	            values={gameValues}
197	            disabled={busy || !steady}
198	          />
199	        </div>
200	      )}
201	
202	      <div className="card">
203	        <h2 className="mb-4 font-semibold">Live stats</h2>
204	        {live ? (
205	          <div className="space-y-4 text-sm">
206	            <div>
207	              <div className="mb-1.5 flex justify-between">
208	                <span className="text-slate-400">CPU</span>
209	                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
210	              </div>
211	              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
212	            </div>
213	            <div>
214	              <div className="mb-1.5 flex justify-between">
215	                <span className="text-slate-400">Memory</span>
216	                <span className="font-semibold">
217	                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
218	                </span>
219	              </div>
220	              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
221	            </div>
222	            <div className="flex justify-between">
223	              <span className="text-slate-400">Uptime</span>
224	              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
225	            </div>
226	            <div className="flex justify-between">
227	              <span className="text-slate-400">Network I/O</span>
228	              <span className="font-mono text-xs">
229	                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
230	              </span>
231	            </div>
232	          </div>
233	        ) : (
234	          <p className="text-sm text-slate-400">
235	            {pveUnavailable
236	              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
237	              : "Live stats appear once the server is provisioned."}
238	          </p>
239	        )}
240	      </div>
241	
242	      <div className="card">
243	        <h2 className="mb-4 font-semibold">Configuration</h2>
244	        <dl className="space-y-2.5 text-sm">
245	          <div className="flex justify-between">
246	            <dt className="text-slate-400">Plan</dt>
247	            <dd>
248	              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
249	              {server.plan.diskGB} GB NVMe
250	            </dd>
251	          </div>
252	          <div className="flex justify-between">
253	            <dt className="text-slate-400">Bandwidth</dt>
254	            <dd>{server.plan.bandwidthTB} TB / month</dd>
255	          </div>
256	          <div className="flex justify-between">
257	            <dt className="text-slate-400">Operating system</dt>
258	            <dd>{server.osTemplate.name}</dd>
259	          </div>
260	          <div className="flex justify-between">
261	            <dt className="text-slate-400">Created</dt>
262	            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
263	          </div>
264	          <div className="flex justify-between">
265	            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
266	            <dd>
267	              {server.isFree
268	                ? "Free — never expires"
269	                : server.expiresAt
270	                  ? server.expiresAt.toISOString().slice(0, 10)
271	                  : "—"}
272	            </dd>
273	          </div>
274	        </dl>
275	      </div>
276	
277	      {!server.isFree ? (
278	        <RenewalCard
279	          serverId={server.id}
280	          autoRenew={server.autoRenew}
281	          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
282	          priceCents={server.plan.priceCents}
283	          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
284	        />
285	      ) : (
286	        <div className="card">
287	          <h2 className="mb-3 font-semibold">Subscription</h2>
288	          <p className="text-sm text-slate-400">
289	            This server is free of charge — no billing, no expiry.
290	          </p>
291	        </div>
292	      )}
293	
294	      <div className="card md:col-span-2">
295	        <h2 className="mb-4 font-semibold">Disk usage</h2>
296	        <DiskUsageChart
297	          serverId={server.id}
298	          planTotalGB={server.plan.diskGB}
299	          available={!!server.vmid && steady}
300	        />
301	      </div>
302	
303	      <div className="card md:col-span-2">
304	        <h2 className="mb-3 font-semibold">Project</h2>
305	        <ProjectAssign
306	          serverId={server.id}
307	          currentProjectId={server.projectId}
308	          projects={projects.map((p) => ({ id: p.id, name: p.name, color: p.color }))}
309	        />
310	      </div>
311	    </div>
312	  );
313	
314	  /* ---------- Tab: Files ---------- */
315	  const filesPanel =
316	    server.status === "RUNNING" ? (
317	      <FileManager serverId={server.id} />
318	    ) : (
319	      <div className="card py-12 text-center">
320	        <h2 className="font-semibold">File manager unavailable</h2>
321	        <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
322	          The in-browser file manager works only while your server is{" "}
323	          <span className="font-medium text-slate-200">running</span>. Start the server to browse,
324	          upload, and edit files over SFTP.
325	        </p>
326	      </div>
327	    );
328	
329	  /* ---------- Tab: Snapshots ---------- */
330	  const snapshotsTab = (
331	    <div className="space-y-6">
332	      <div className="card">
333	        <h2 className="mb-4 font-semibold">Create snapshot</h2>
334	        <CreateSnapshotForm serverId={server.id} disabled={busy || !steady} />
335	      </div>
336	      <div className="card p-0">
337	        <p className="section-label px-4 pt-4">Snapshots</p>
338	        {pveUnavailable && snapshots.length === 0 ? (
339	          <p className="px-4 py-6 text-sm text-amber-300">
340	            Could not load snapshots — the hypervisor is briefly unavailable. Try again in a moment.
341	          </p>
342	        ) : snapshots.length === 0 ? (
343	          <p className="px-4 py-6 text-sm text-slate-400">
344	            No snapshots yet. Take one before risky changes so you can roll back instantly.
345	          </p>
346	        ) : (
347	          <table className="table-shell mt-2">
348	            <thead>
349	              <tr>
350	                <th>Name</th>
351	                <th>Taken</th>
352	                <th>Description</th>
353	                <th className="text-right">Actions</th>
354	              </tr>
355	            </thead>
356	            <tbody>
357	              {snapshots.map((s) => (
358	                <tr key={s.name}>
359	                  <td className="font-mono text-xs">{s.name}</td>
360	                  <td className="text-slate-400">
361	                    {s.snaptime ? new Date(s.snaptime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
362	                  </td>
363	                  <td className="text-slate-400">{s.description || "—"}</td>
364	                  <td>
365	                    <SnapshotActions serverId={server.id} name={s.name} disabled={busy || !steady} />
366	                  </td>
367	                </tr>
368	              ))}
369	            </tbody>
370	          </table>
371	        )}
372	      </div>
373	      <p className="text-xs text-slate-500">
374	        Snapshots live on the same storage as your server — use backups for disaster recovery.
375	      </p>
376	    </div>
377	  );
378	
379	  /* ---------- Tab: Backups ---------- */
380	  const backupsTab = (
381	    <div className="space-y-6">
382	      <BackupSchedule
383	        serverId={server.id}
384	        autoBackup={server.autoBackup}
385	        backupIntervalHours={server.backupIntervalHours}
386	        lastAutoBackup={server.lastAutoBackup ? server.lastAutoBackup.toISOString() : null}
387	      />
388	      <div className="card flex flex-wrap items-center justify-between gap-4">
389	        <div>
390	          <h2 className="font-semibold">Backups</h2>
391	          <p className="mt-1 text-sm text-slate-400">
392	            Full-image backups stored on a separate 4 TB pool, independent from your server&apos;s NVMe storage.
393	          </p>
394	        </div>
395	        <CreateBackupButton serverId={server.id} disabled={busy || !steady} />
396	      </div>
397	      <div className="card p-0">
398	        {pveUnavailable && backups.length === 0 ? (
399	          <p className="px-4 py-6 text-sm text-amber-300">
400	            Could not load backups — the hypervisor is briefly unavailable. Try again in a moment.
401	          </p>
402	        ) : backups.length === 0 ? (
403	          <p className="px-4 py-6 text-sm text-slate-400">
404	            No backups yet. Create one now — restores are handled by support within minutes.
405	          </p>
406	        ) : (
407	          <table className="table-shell">
408	            <thead>
409	              <tr>
410	                <th>Backup</th>
411	                <th>Created</th>
412	                <th className="text-right">Size</th>
413	              </tr>
414	            </thead>
415	            <tbody>
416	              {backups.map((b) => (
417	                <tr key={b.volid}>
418	                  <td className="font-mono text-xs">{b.volid.split("/").pop()}</td>
419	                  <td className="text-slate-400">
420	                    {b.ctime ? new Date(b.ctime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
421	                  </td>
422	                  <td className="text-right text-slate-400">{fmtBytes(b.size ?? 0)}</td>
423	                </tr>
424	              ))}
425	            </tbody>
426	          </table>
427	        )}
428	      </div>
429	      <BackupRestore
430	        serverId={server.id}
431	        backups={backups}
432	        unavailable={pveUnavailable}
433	        disabled={busy || !steady}
434	      />
435	    </div>
436	  );
437	
438	  /* ---------- Tab: Networking ---------- */
439	  const networking = (
440	    <div className="space-y-6">
441	      <div className="glass p-4 text-sm text-slate-300">
442	        Your server sits behind NAT on a private network ({server.ipAddress ?? "10.20.0.x"}). Public
443	        ports on <span className="font-mono text-brand-300">{publicIp}</span> are forwarded to ports
444	        inside your VM — connect to{" "}
445	        <span className="font-mono text-brand-300">{publicIp}:&lt;public port&gt;</span> to reach a
446	        forwarded service.
447	      </div>
448	
449	      <div className="card p-0">
450	        <p className="section-label px-4 pt-4">Port forwards</p>
451	        <table className="table-shell mt-2">
452	          <thead>
453	            <tr>
454	              <th>Public endpoint</th>
455	              <th>Guest port</th>
456	              <th>Protocol</th>
457	              <th className="text-right">Actions</th>
458	            </tr>
459	          </thead>
460	          <tbody>
461	            <tr>
462	              <td className="font-mono text-xs">
463	                {server.sshPort ? `${publicIp}:${server.sshPort}` : "—"}
464	              </td>
465	              <td className="font-mono text-xs">22</td>
466	              <td className="text-slate-400">tcp</td>
467	              <td className="text-right">
468	                <Badge tone="slate">SSH — managed</Badge>
469	              </td>
470	            </tr>
471	            {server.portForwards.map((f) => (
472	              <tr key={f.id}>
473	                <td className="font-mono text-xs">
474	                  {publicIp}:{f.publicPort}
475	                </td>
476	                <td className="font-mono text-xs">{f.guestPort}</td>
477	                <td className="text-slate-400">{f.protocol}</td>
478	                <td className="text-right">
479	                  <DeleteForwardButton serverId={server.id} forwardId={f.id} />
480	                </td>
481	              </tr>
482	            ))}
483	          </tbody>
484	        </table>
485	        {server.portForwards.length === 0 && (
486	          <p className="px-4 pb-4 text-sm text-slate-500">
487	            No custom forwards yet — add one below to expose a web server, game server, or any other
488	            service.
489	          </p>
490	        )}
491	      </div>
492	
493	      <div className="card">
494	        <h2 className="mb-4 font-semibold">Quick firewall presets</h2>
495	        <FirewallPresets
496	          serverId={server.id}
497	          disabled={busy || !steady}
498	          existingGuestPorts={server.portForwards.map((f) => f.guestPort)}
499	        />
500	      </div>
501	
502	      <div className="card">
503	        <h2 className="mb-4 font-semibold">Add port forward</h2>
504	        <AddForwardForm serverId={server.id} />
505	        <p className="mt-3 text-xs text-slate-500">
506	          A free public port (20000–29999) is assigned automatically. Up to 10 forwards per server.
507	        </p>
508	      </div>
509	    </div>
510	  );
511	
512	  /* ---------- Tab: Resize ---------- */
513	  const resize = (
514	    <div className="space-y-6">
515	      <ResizePicker
516	        serverId={server.id}
517	        currentPlanId={server.planId}
518	        currentDiskGB={server.plan.diskGB}
519	        plans={activePlans.map((p) => ({
520	          id: p.id,
521	          name: p.name,
522	          cpuCores: p.cpuCores,
523	          ramMB: p.ramMB,
524	          diskGB: p.diskGB,
525	          bandwidthTB: p.bandwidthTB,
526	          priceCents: p.priceCents,
527	        }))}
528	        disabled={busy || !steady}
529	      />
530	
531	      <ResizeDown
532	        serverId={server.id}
533	        currentPlanId={server.planId}
534	        currentDiskGB={server.plan.diskGB}
535	        currentPriceCents={server.plan.priceCents}
536	        termMonths={server.termMonths}
537	        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
538	        isFree={server.isFree}
539	        plans={activePlans.map((p) => ({
540	          id: p.id,
541	          name: p.name,
542	          cpuCores: p.cpuCores,
543	          ramMB: p.ramMB,
544	          diskGB: p.diskGB,
545	          bandwidthTB: p.bandwidthTB,
546	          priceCents: p.priceCents,
547	        }))}
548	        disabled={busy || !steady}
549	      />
550	
551	      <ReinstallOs
552	        serverId={server.id}
553	        currentOsTemplateId={server.osTemplateId}
554	        currentOsName={server.osTemplate.name}
555	        planRamMB={server.plan.ramMB}
556	        planDiskGB={server.plan.diskGB}
557	        templates={osTemplates.map((t) => ({
558	          id: t.id,
