"use client";

import { useState } from "react";
import { WebTerminal } from "@/components/customer/WebTerminal";

/**
 * "Open terminal" button for the server detail page. Opens the shared
 * WebTerminal panel wired to this single server. Reuses the exact component
 * from the Claude Code hub — the `connect` field mirrors the hub's list shape.
 */
export function OpenTerminalButton({
  servers,
}: {
  servers: { id: string; hostname: string; connect: string }[];
}) {
  const [open, setOpen] = useState(false);

  return (
    <>
      <button className="btn-secondary" onClick={() => setOpen(true)}>
        Open terminal
      </button>
      {open && (
        <WebTerminal
          servers={servers.map((s) => ({ id: s.id, hostname: s.hostname }))}
          onClose={() => setOpen(false)}
        />
      )}
    </>
  );
}

