function Social({ label, path, href }: { label: string; path: React.ReactNode; href?: string }) {
  const className =
    "flex h-9 w-9 items-center justify-center rounded-xl border border-white/[0.08] bg-white/[0.03] text-slate-500 transition-colors hover:border-white/20 hover:text-slate-300";
  const icon = (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
      {path}
    </svg>
  );
  // Real link when the profile URL is configured; otherwise decorative
  // (non-linking) so we never render a dead link.
  return href ? (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      title={label}
      aria-label={label}
      className={className}
    >
      {icon}
    </a>
  ) : (
    <span title={label} aria-label={label} className={className}>
      {icon}
    </span>
  );
}
